// Generates crates/sirene-core/src/math/functions_data.rs from KaTeX's function registry
// (spec/latex-math.md, LMATH-12). Development tool: the generated file is checked in.
//
// Setup (once): the KaTeX checkout described in scripts/katex-fixtures.mjs, at tag v0.19.1.
// Run:
//   node --no-warnings scripts/katex-functions.mjs
//
// KaTeX's parser dispatches a command to a function by name: how many arguments it takes, where
// it may appear, and which node it builds. Node 24 reads the TypeScript directly (with the
// resolver hook of scripts/katex-ts-loader.mjs), so this reads the real registry. The Rust file
// keeps one byte-sorted row per name, written as the source writes it (`\sum`, or the bare
// character for `$` and the operator characters). Adapted from KaTeX, MIT licensed, Copyright
// (c) 2013-2020 Khan Academy and other contributors; see THIRD-PARTY-NOTICES.

import { register } from "node:module";
import { writeFileSync } from "node:fs";

register("./katex-ts-loader.mjs", import.meta.url);
await import(new URL("../local/katex/src/functions.ts", import.meta.url));
const { _functions } = await import(new URL("../local/katex/src/defineFunction.ts", import.meta.url));

// One letter per argument: how the parser reads it (`original` is the default).
const TYPE_CODES = { original: "o", math: "m", text: "t", primitive: "p", color: "c", size: "s", url: "u", hbox: "h", raw: "r" };

const rows = [];
for (const [name, spec] of Object.entries(_functions)) {
  rows.push({
    name,
    kind: spec.type,
    args: spec.numArgs,
    optional: spec.numOptionalArgs ?? 0,
    text: !!spec.allowedInText,
    math: spec.allowedInMath ?? true,
    argument: !!spec.allowedInArgument,
    primitive: !!spec.primitive,
    infix: !!spec.infix,
    types: Array.from({ length: spec.numArgs + (spec.numOptionalArgs ?? 0) }, (_, i) => TYPE_CODES[spec.argTypes?.[i] ?? "original"]).join(""),
  });
}
rows.sort((a, b) => Buffer.compare(Buffer.from(a.name), Buffer.from(b.name)));

// ASCII-only Rust string literals; the operator characters are written as escapes.
const q = (s) => {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"' || ch === "\\") out += "\\" + ch;
    else if (cp >= 0x20 && cp < 0x7f) out += ch;
    else out += `\\u{${cp.toString(16)}}`;
  }
  return out + '"';
};

let out = `// Generated by scripts/katex-functions.mjs from KaTeX 0.19.1's function registry. Do not edit.
// Adapted from KaTeX, MIT licensed, Copyright (c) 2013-2020 Khan Academy and other contributors;
// see THIRD-PARTY-NOTICES.

use super::functions::Row;

/// Every command the parser reads as a function, sorted by name.
#[rustfmt::skip]
pub(super) const FUNCTIONS: &[Row] = &[
`;
for (const r of rows) {
  out += `    (${q(r.name)}, ${q(r.kind)}, ${r.args}, ${r.optional}, ${r.text}, ${r.math}, ${r.argument}, ${r.primitive}, ${r.infix}, ${q(r.types)}),\n`;
}
out += "];\n";
writeFileSync(new URL("../crates/sirene-core/src/math/functions_data.rs", import.meta.url), out);
console.log(`${rows.length} functions`);
